import {$,esc,showToast} from "./dom.js";
import {appState,productLanguageConfig,rules,supportedLanguages} from "./state.js";
import {renderAnnotations} from "./annotations.js";

const languageName=code=>supportedLanguages.find(item=>item[0]===code)?.[1]||code;
const clone=value=>JSON.parse(JSON.stringify(value));
const productRules=()=>rules.filter(rule=>rule.productId===appState.selectedProductId);
const committed=()=>productLanguageConfig[appState.selectedProductId]??(productLanguageConfig[appState.selectedProductId]={selectedLocales:["en-US"],values:{}});
const productRows=()=>productRules().flatMap(rule=>[{key:`${rule.id}.title`,label:`${rule.name} · Title`,limit:100,defaultValue:rule.title},{key:`${rule.id}.body`,label:`${rule.name} · Body`,limit:200,defaultValue:"Your device needs attention."}]);
let productDraft=null;

function valuesFor(draft,row){return draft.values[row.key]??(draft.values[row.key]={"en-US":row.defaultValue})}
function issuesFor(draft,rows){const issues=[];rows.forEach(row=>draft.selectedLocales.forEach(code=>{const value=valuesFor(draft,row)[code]||"";if(!value.trim())issues.push(`${row.label} · ${languageName(code)} 未填写`);else if(value.length>row.limit)issues.push(`${row.label} · ${languageName(code)} 超过 ${row.limit} 字符`)}));return issues}
function localeChoices(draft){return `<div class="locale-grid" data-anchor="language-selection">${supportedLanguages.map(([code,name])=>{const checked=draft.selectedLocales.includes(code),locked=code==="en-US";return `<label class="locale-option ${checked?"selected":""}"><input type="checkbox" data-locale="${esc(code)}" ${checked?"checked":""} ${locked?"disabled":""}><span><strong>${esc(name)}</strong><small>${esc(code)}${locked?" · 默认":""}</small></span></label>`}).join("")}</div>`}
function matrix(draft,rows,anchor,ruleOnly=false){return `<div class="matrix-wrap" data-anchor="${anchor}"><table class="lang-matrix ${ruleOnly?"rule-language-matrix":"product-language-matrix"}"><thead><tr><th style="min-width:${ruleOnly?"148":"220"}px">输入项</th>${draft.selectedLocales.map(code=>`<th style="min-width:220px">${esc(languageName(code))}<small>${esc(code)}</small></th>`).join("")}</tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(ruleOnly?row.label:row.label)}</strong><div class="secondary-cell">${ruleOnly?"":`${esc(row.key)} · `}最多 ${row.limit} 字符</div></td>${draft.selectedLocales.map(code=>`<td><textarea data-language-key="${esc(row.key)}" data-language-locale="${esc(code)}" maxlength="${row.limit}" placeholder="${esc(languageName(code))}">${esc(valuesFor(draft,row)[code]||"")}</textarea></td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function validation(issues,anchor,subject){return `<div class="form-section" data-anchor="${anchor}"><div class="section-title"><h3>保存检查</h3><p>${issues.length?"还有未填写内容":"已可以保存"}</p></div>${issues.length?`<div class="help-alert danger">${issues.slice(0,4).map(esc).join("；")}${issues.length>4?`；还有 ${issues.length-4} 项`:""}</div>`:`<div class="help-alert success">${subject}已选语言的内容都已填写。</div>`}</div>`}

function productBody(){const rows=productRows(),issues=issuesFor(productDraft,rows);return `<div class="help-alert" data-anchor="product-language-intro"><strong>统一多语言。</strong> 当前产品的所有规则都在这一张表中维护。这里的勾选和内容先保留在抽屉内，点击保存后才会影响规则。</div><div class="form-section"><div class="section-title"><h3>选择语言</h3><p>English 必选，其他 17 个语言按需选择</p></div>${localeChoices(productDraft)}</div><div class="form-section"><div class="section-title"><h3>多语言大表</h3><p>每行一个输入项，每列一种语言</p></div><div class="inline-actions"><button class="el-btn" data-export-language>导出当前草稿</button><span class="secondary-cell">取消不会保存语言选择或内容。</span></div>${matrix(productDraft,rows,"product-language-matrix")}</div>${validation(issues,"product-language-validation","当前产品")}`}
function productDrawer(){return `<div class="drawer-host is-open" id="languageDrawer" style="z-index:1400"><div class="drawer-mask" data-language-cancel></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="统一配置多语言"><header class="drawer-header"><div class="drawer-title"><h2>统一配置多语言</h2><p>当前产品 · 所有推送规则共用一张 KV 大表</p></div><button class="icon-btn" data-language-cancel>×</button></header><div class="drawer-main"><div class="drawer-body"><section class="drawer-content">${productBody()}</section></div></div><footer class="drawer-footer"><span class="save-hint">取消不保存；仅校验已选语言</span><div class="footer-actions"><button class="el-btn" data-language-cancel>取消</button><button class="el-btn el-btn--primary" data-language-save>保存</button></div></footer></aside></div>`}
function exportProductDraft(){const rows=productRows(),header=["input key",...productDraft.selectedLocales.map(languageName)],content=[header,...rows.map(row=>[row.key,...productDraft.selectedLocales.map(code=>valuesFor(productDraft,row)[code]||"")])].map(line=>line.map(value=>String(value).replace(/\t/g," ")).join("\t")).join("\n"),blob=new Blob(["\uFEFF",content],{type:"text/tab-separated-values;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`${appState.selectedProductId}-push-language-draft.tsv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),0);showToast("已导出当前草稿")}
function renderProduct(){const host=$("#languageDrawer");if(!host)return;host.outerHTML=productDrawer();wireProduct()}
function closeProduct(onClose){const host=$("#languageDrawer");if(!host)return;productDraft=null;host.remove();onClose?.()}
function wireProduct(onClose){const host=$("#languageDrawer");if(!host)return;host.querySelectorAll("[data-language-cancel]").forEach(item=>item.onclick=()=>closeProduct(onClose));host.querySelectorAll("[data-locale]").forEach(input=>input.onchange=()=>{const code=input.dataset.locale;productDraft.selectedLocales=input.checked?[...new Set([...productDraft.selectedLocales,code])]:productDraft.selectedLocales.filter(value=>value!==code);renderProduct()});host.querySelectorAll("[data-language-key]").forEach(input=>input.oninput=()=>{const row=productRows().find(item=>item.key===input.dataset.languageKey);if(row)valuesFor(productDraft,row)[input.dataset.languageLocale]=input.value});host.querySelector("[data-export-language]")?.addEventListener("click",exportProductDraft);host.querySelector("[data-language-save]")?.addEventListener("click",()=>{const issues=issuesFor(productDraft,productRows());if(issues.length){showToast("请补全已选语言的内容","error");return}Object.assign(committed(),clone(productDraft));productRules().forEach(rule=>rule.languages=String(productDraft.selectedLocales.length));showToast("产品多语言已保存");closeProduct(onClose)})}
export function openProductLanguageDrawer({onClose}={}){productDraft=clone(committed());productDraft.values??={};$("#overlayRoot").insertAdjacentHTML("beforeend",productDrawer());renderAnnotations("language","统一配置多语言");wireProduct(onClose)}
